const TYPES = ["feat", "fix", "docs", "style", "refactor", "perf", "test", "build", "ci", "chore", "revert"];
const SUBJECT = new RegExp(`^(${TYPES.join("|")})(\\([a-z0-9-]+\\))?!?: \\S.*$`);
const MAX_SUBJECT = 72;

/** Conventional Commits check. Returns problems; empty means the message is fine. */
export function validateCommitMessage(message: string): string[] {
  const lines = message.replaceAll("\r\n", "\n").split("\n").filter((line) => !line.startsWith("#"));
  const subject = (lines[0] ?? "").trim();

  // Merge and revert commits are generated by git.
  if (subject.startsWith("Merge ") || subject.startsWith('Revert "')) {
    return [];
  }

  const problems: string[] = [];
  if (!SUBJECT.test(subject)) {
    problems.push(`Subject must look like "type(scope): summary" with type one of: ${TYPES.join(", ")}.`);
  }
  if (subject.length > MAX_SUBJECT) {
    problems.push(`Subject is ${subject.length} characters. Keep it to ${MAX_SUBJECT} or fewer.`);
  }
  if (subject.endsWith(".")) {
    problems.push("Subject must not end with a period.");
  }
  if (lines.length > 1 && (lines[1] ?? "").trim() !== "") {
    problems.push("Leave a blank line between the subject and the body.");
  }
  return problems;
}
